def has_all_codes(s, k):
    need = 1 << k
    if len(s) < need + k - 1:
        return False                                                        # not enough characters to even possibly contain every code
    mask = need - 1
    seen = set()
    window_hash = 0
    for i, ch in enumerate(s):
        window_hash = ((window_hash << 1) | (1 if ch == '1' else 0)) & mask   # roll the hash: shift left, add new bit, drop the oldest bit
        if i >= k - 1:
            seen.add(window_hash)
    return len(seen) == need


if __name__ == "__main__":
    print(has_all_codes("00110110", 2))

