public class Main {
    boolean hasAllCodes(String s, int k) {
        int need = 1 << k;
        if (s.length() < need + k - 1) return false;                             // not enough characters to even possibly contain every code
        int mask = need - 1;
        Set<Integer> seen = new HashSet<>();
        int windowHash = 0;
        for (int i = 0; i < s.length(); i++) {
            windowHash = ((windowHash << 1) | (s.charAt(i) - '0')) & mask;          // roll the hash: shift left, add new bit, drop the oldest bit
            if (i >= k - 1) seen.add(windowHash);
        }
        return seen.size() == need;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.hasAllCodes("00110110", 2));
    }
}

