#include <bits/stdc++.h>
using namespace std;

bool hasAllCodes(string s, int k) {
    int need = 1 << k;
    if ((int)s.size() < need + k - 1) return false;                            // not enough characters to even possibly contain every code
    int mask = need - 1;
    unordered_set<int> seen;
    int windowHash = 0;
    for (int i = 0; i < (int)s.size(); i++) {
        windowHash = ((windowHash << 1) | (s[i] - '0')) & mask;                   // roll the hash: shift left, add new bit, drop the oldest bit
        if (i >= k - 1) seen.insert(windowHash);
    }
    return (int)seen.size() == need;
}

int main() {
    cout << (hasAllCodes("00110110", 2) ? "true" : "false") << endl;
    return 0;
}
